window.GitDesignApp=(()=>{
 const D=window.GitDesignData,M=window.GitDesignModel.create();let s=M.state,observer=null,toastTimer,logOpen=false,graphData=[],renderContext=null;
 const scrollMemory=new Map();
 function context(){return {scope:s.scope,route:s.route,file:s.selectedFile,group:s.group,commit:s.historySelected,index:s.historyFile,module:s.selectedModule,stash:s.selectedStash}}
 function scrollKey(c,el){return [c.scope,c.route,el.className,el.classList.contains('diff-scroll')?[c.file,c.group,c.commit,c.index,c.stash].join(':'):el.classList.contains('module-main')?c.module:''].join('|')}
 function rememberScroll(){if(renderContext)$('root').querySelectorAll('.diff-scroll,.history-scroll,.files-list,.content-scroll,.module-main').forEach(el=>scrollMemory.set(scrollKey(renderContext,el),[el.scrollTop,el.scrollLeft]))}
 function restoreScroll(c){$('root').querySelectorAll('.diff-scroll,.history-scroll,.files-list,.content-scroll,.module-main').forEach(el=>{const pos=scrollMemory.get(scrollKey(c,el));if(pos){el.scrollTop=pos[0];el.scrollLeft=pos[1]}})}
 const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const paths={repo:'M4 19V5a2 2 0 0 1 2-2h14v18H6a2 2 0 0 1 0-4h14M8 7h7m-7 4h5',branch:'M6 8v8m12-7c0 6-12 2-12 7',changes:'M5 3h9l5 5v13H5V3Zm9 0v6h5M8 13h8m-8 4h5',history:'M3 11a9 9 0 1 1 2 7M3 4v7h7m2-5v6l4 2',tree:'M6 9v6m0-3h12v3M3 3h7v6H3V3Zm11 12h7v6h-7v-6ZM3 15h7v6H3v-6Z',box:'m12 3 9 5-9 5-9-5 9-5Zm-9 5v9l9 5 9-5V8m-9 5v9',stash:'M3 4h18v5H3V4Zm2 5v12h14V9m-10 4h6',search:'m15 15 5 5',down:'m7 10 5 5 5-5',fetch:'M20 8A8 8 0 0 0 6 5L3 8m0-5v5h5m-4 8a8 8 0 0 0 14 3l3-3m0 5v-5h-5',pull:'M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4',push:'M12 17V4m-5 5 5-5 5 5M4 17v4h16v-4',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',file:'M5 3h9l5 5v13H5V3Zm9 0v6h5',arrow:'M4 12h16m-6-6 6 6-6 6',terminal:'m4 6 6 6-6 6m9 0h7',settings:'M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1m-12.8 0 2.1-2.1m8.6-8.6 2.1-2.1',alert:'m12 3 10 18H2L12 3Zm0 6v5m0 3v.1',merge:'M6 5v14m12-14v3c0 5-12 3-12 8',folder:'M3 6V4h7l3 3h8v13H3V6Z',link:'m8 16 8-8M9 7l2-2a5 5 0 0 1 7 7l-2 2M8 10l-2 2a5 5 0 0 0 7 7l2-2',undo:'M3 10h11a6 6 0 0 1 0 12M3 10l6-6m-6 6 6 6'};
 function icon(name){let extra=name==='branch'?'<circle cx="6" cy="5" r="3"/><circle cx="18" cy="6" r="3"/><circle cx="6" cy="19" r="3"/>':name==='search'?'<circle cx="10" cy="10" r="6.5"/>':name==='settings'?'<circle cx="12" cy="12" r="5"/>':name==='merge'?'<circle cx="6" cy="4" r="2"/><circle cx="18" cy="4" r="2"/><circle cx="6" cy="20" r="2"/>':'';return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/>${extra}</svg>`}
 const button=(label,action,attrs='',classes='')=>`<button class="button ${classes}" data-action="${action}" ${attrs}>${label}</button>`;
 const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
 function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4800)}
 function navigate(route){s=M.state;s.route=route;s.modal=null;s.empty=false;if(route==='history'){s.historySelected=M.head();s.historyFile=0}if(location.hash!=='#'+route)location.hash=route;render()}
 function modal(type,data={}){s=M.state;s.modal={type,...data,error:null};render();requestAnimationFrame(()=>{const el=$('overlay-root').querySelector('input:not([type="checkbox"]):not(:disabled),select:not(:disabled),textarea:not(:disabled)')||$('overlay-root').querySelector('button');el?.focus()})}
 function closeModal(){s=M.state;s.modal=null;render()}
 function applyAppearance(){const root=document.documentElement,t=s.settings.theme;if(t==='system')delete root.dataset.theme;else root.dataset.theme=t;const dark=t==='dark'||t==='system'&&matchMedia('(prefers-color-scheme:dark)').matches;const palette={teal:['#147e82','#65bdc0'],blue:['#365f9c','#93b6ee'],plum:['#8c507b','#d9a9cc']};root.style.setProperty('--accent',palette[s.settings.accent][dark?1:0]);root.style.setProperty('--font-size',s.settings.font+'px');$('window').classList.toggle('compact',s.settings.density==='compact')}
 function titlebar(){const c=M.current();return `<div class="titlebar"><div class="traffic" aria-hidden="true"><i></i><i></i><i></i></div><div class="breadcrumbs"><button data-action="repositories">${icon('repo')}sample-workspace ${icon('down')}</button><span class="divider">/</span><button class="context" data-action="${M.isChild()?'submodules':'worktrees'}">${esc(c.name)}</button>${M.isChild()?badge('Submodule'):''}</div><div class="spacer"></div><button class="command-trigger" data-action="command">${icon('search')}<span>查找与操作</span><kbd>⌘ K</kbd></button><button class="icon-button" data-action="settings" aria-label="偏好设置" title="偏好设置">${icon('settings')}</button></div>`}
 function sidebar(){const child=M.isChild();return `<aside class="sidebar"><button class="repo-select" data-action="repositories"><span class="repo-icon">${icon('repo')}</span><span><strong>sample-workspace</strong><small>${child?'子模块 · '+esc(M.current().name):'本地示例仓库'}</small></span></button><nav>${D.routes.map(([id,i,label])=>`<button class="nav-item ${s.route===id?'active':''}" data-action="nav" data-route="${id}">${icon(i)}${label}${id==='workspace'?'<span class="count">'+M.files().length+'</span>':id==='stash'?'<span class="count">'+s.stashes.filter(x=>x.scope===s.scope).length+'</span>':''}</button>`).join('')}</nav>${s.operation||s.route==='rebase'?`<div class="nav-section">当前操作</div><button class="nav-item ${['rebase','conflicts'].includes(s.route)?'active':''}" data-action="nav" data-route="${s.operation?'conflicts':'rebase'}">${icon('merge')}${s.operation?(s.operation.kind==='rebase'?'Rebase 已暂停':'合并冲突'):'Rebase 计划'}${s.operation?'<span class="count">1</span>':''}</button>`:''}<div class="nav-section">${child?'仓库上下文':'本地分支'}<button class="icon-button" data-action="new-branch" aria-label="创建分支">${icon('plus')}</button></div>${child?`<button class="nav-item branch-nav" data-action="back-parent">${icon('arrow')}返回${s.scope==='tokenizer'?'core':'主仓库'}</button><div class="nav-item branch-nav">${icon('branch')}${esc(M.current().branch||'detached HEAD')}</div>`:s.branches.slice(0,5).map(b=>`<button class="nav-item branch-nav" data-action="checkout" data-name="${esc(b.name)}">${icon('branch')}${esc(b.name)}${b.name===M.current().branch?'<span class="dot good"></span>':''}</button>`).join('')}<div class="nav-section">Submodules</div>${s.modules.filter(m=>m.parent===s.scope).map(m=>`<button class="nav-item branch-nav" data-action="select-module" data-id="${m.id}">${icon('box')}${esc(m.path)}<span class="dot ${m.initialized&&(M.dirty(m.id)||m.head!==m.pinned)?'warn':''}"></span></button>`).join('')||'<div class="file-empty">当前上下文没有子模块</div>'}<div class="side-foot"><span class="dot good"></span>演示状态 · 不执行真实命令</div></aside>`}
 function toolbar(){const c=M.current();return `<div class="toolbar"><button class="branch-picker" data-action="branches">${icon('branch')}<span>${esc(c.branch||'detached HEAD')}</span>${icon('down')}<span class="ahead">${c.ahead?'↑ '+c.ahead:'与上游一致'}</span></button><div class="button-row">${button(icon('fetch')+'Fetch','fetch','','quiet')}${button(icon('pull')+'Pull','pull')}${button(icon('push')+'Push'+(c.ahead?'<span class="split-button">'+c.ahead+'</span>':''),'push')}</div></div>`}
 function operationBanner(){if(!s.operation)return '';const op=s.operation;return `<div class="operation-banner"><span>${icon('alert')} <strong>${op.kind==='rebase'?'Rebase 暂停':'合并尚未完成'}</strong> · ${s.conflict.resolved?'冲突已标记解决，等待继续':'1 个文件需要处理'}${op.kind==='rebase'?' · 第 '+op.step+' / '+op.total+' 条提交':''}</span><div class="button-row">${button('查看冲突','conflicts')}${button('中止…','abort','','quiet')}</div></div>`}
 function statusbar(){return `<footer class="statusbar"><div><span class="truncate">${icon('branch')} ${esc(M.current().branch||M.head())}</span><span class="optional">${M.isChild()?'Submodule · '+esc(M.current().name):'Worktree · '+esc(M.current().name)}</span></div><div>${s.lastAction?`<button data-action="undo">${icon('undo')}恢复上一步</button>`:''}<span class="optional">演示数据</span><button data-action="log">${icon('terminal')}操作记录</button></div></footer>`}
 function viewHeader(title,desc,actions=''){return `<header class="view-header"><div><h2>${title}</h2><p>${desc}</p></div><div class="button-row">${actions}</div></header>`}
 function empty(title,desc,actions='',i='check'){return `<div class="blank">${icon(i)}<h3>${title}</h3><p>${desc}</p><div class="button-row">${actions}</div></div>`}
 function highlight(text){const str=esc(text);if(text.trim().startsWith('//'))return `<span class="syntax-comment">${str}</span>`;return str.replace(/(&quot;.*?&quot;)/g,'<span class="syntax-string">$1</span>').replace(/\b(pub|async|fn|let|impl|use|mut|self|return|const)\b/g,'<span class="syntax-key">$1</span>')}
 function codeTable(rows,selectable=false){if(s.diffMode==='split')return `<table class="code-table split" aria-label="左右差异"><tbody>${rows.map(r=>`<tr class="${r.t} ${selectable&&r.t!=='ctx'?'selectable':''} ${s.selectedLines.includes(r.id)?'selected':''}" ${selectable&&r.t!=='ctx'?`data-action="select-line" data-id="${esc(r.id)}" tabindex="0" role="button" aria-pressed="${s.selectedLines.includes(r.id)}" aria-label="${r.t==='add'?'新增':'删除'}：${esc(r.text)}"`:''}><td class="num">${r.old??''}</td><td class="code">${r.t==='add'?' ':highlight(r.text)||' '}</td><td class="num split-border">${r.next??''}</td><td class="code">${r.t==='del'?' ':highlight(r.text)||' '}</td></tr>`).join('')}</tbody></table>`;return `<table class="code-table" aria-label="统一差异"><tbody>${rows.map(r=>`<tr class="${r.t} ${selectable&&r.t!=='ctx'?'selectable':''} ${s.selectedLines.includes(r.id)?'selected':''}" ${selectable&&r.t!=='ctx'?`data-action="select-line" data-id="${esc(r.id)}" tabindex="0" role="button" aria-pressed="${s.selectedLines.includes(r.id)}" aria-label="${r.t==='add'?'新增':'删除'}：${esc(r.text)}"`:''}><td class="num">${r.old??''}</td><td class="num">${r.next??''}</td><td class="sign">${r.t==='add'?'+':r.t==='del'?'−':''}</td><td class="code">${highlight(r.text)||' '}</td></tr>`).join('')}</tbody></table>`}
 function diffSwitch(){return `<div class="segmented" aria-label="Diff 方式"><button data-action="diff-mode" data-mode="unified" class="${s.diffMode==='unified'?'active':''}" aria-pressed="${s.diffMode==='unified'}">统一</button><button data-action="diff-mode" data-mode="split" class="${s.diffMode==='split'?'active':''}" aria-pressed="${s.diffMode==='split'}">左右</button></div>`}
 function diff(p,selectable=false){if(!p)return `<section class="diff-pane">${empty('没有选中的文件','从左侧选择一个文件查看改动。','','file')}</section>`;const rows=selectable?p.rows.filter(r=>r.t==='ctx'||!r.done&&r.staged===(s.group==='staged')):p.rows;const add=rows.filter(r=>r.t==='add').length,del=rows.filter(r=>r.t==='del').length;return `<section class="diff-pane"><header class="pane-head"><span class="diff-path" title="${esc(p.path)}">${esc(p.path)}</span>${diffSwitch()}</header><div class="diff-meta"><div class="meta">${badge(selectable?s.group==='staged'?'已暂存':'工作区改动':'提交差异',selectable&&s.group==='staged'?'good':'')}<span class="mono good">+${add}</span><span class="mono danger">−${del}</span></div>${selectable?button(s.group==='staged'?'取消暂存':'暂存文件','stage-file','data-id="'+esc(p.id)+'"'):''}</div><div class="diff-scroll"><div class="hunk-bar"><code>@@ ${rows[0]?.old||1} · ${rows[0]?.next||1} @@</code>${selectable?`<button class="text-button" data-action="stage-file" data-id="${esc(p.id)}">${s.group==='staged'?'取消暂存此片段':'暂存此片段'}</button>`:'<span>基于第一父提交比较</span>'}</div>${codeTable(rows,selectable)}</div><footer class="diff-footer"><span>${selectable?(s.selectedLines.length?'已选择 '+s.selectedLines.length+' 行':'点击增删行选择代码'):'UTF-8 · 只读比较'}</span>${selectable?`<button class="text-button" data-action="stage-lines" ${s.selectedLines.length?'':'disabled'}>${s.group==='staged'?'取消暂存所选行':'暂存所选行'} <kbd>S</kbd></button>`:''}</footer></section>`}
 function fileRow(f,action,attrs='',active=false){const parts=f.path.split('/'),name=parts.pop();return `<button class="file-row ${active?'active':''}" data-action="${action}" ${attrs}>${icon(f.type==='module'?'box':'file')}<span class="file-info"><strong>${esc(name)}</strong><small>${esc(parts.join('/')||'仓库根目录')}</small></span>${f.status?'<span class="file-status">'+esc(f.status)+'</span>':''}</button>`}
 function workspace(){M.ensureSelection();const c=M.current(),f=M.selectedFile(),staged=M.groupFiles('staged').length;return `<div class="view"><div class="workspace"><section class="files-pane"><div class="pane-head"><h3>文件改动 <small>${M.files().length}</small></h3><button class="icon-button" data-action="refresh" aria-label="刷新">${icon('fetch')}</button></div><div class="file-search"><label class="search">${icon('search')}<input id="file-filter" data-bind="filter" value="${esc(s.filter)}" placeholder="筛选路径…" aria-label="筛选文件"></label></div><div class="files-list">${['unstaged','staged'].map(g=>{const files=M.groupFiles(g),visible=files.filter(f=>f.path.toLowerCase().includes(s.filter.toLowerCase()));return `<div class="file-group"><span><strong>${g==='staged'?'已暂存':'未暂存'}</strong> ${files.length}</span><button class="text-button" data-action="stage-all" data-stage="${g==='unstaged'}">${g==='staged'?'全部取消':'全部暂存'}</button></div>${visible.map(f=>fileRow(f,'select-file',`data-id="${esc(f.id)}" data-group="${g}"`,f.id===s.selectedFile&&g===s.group)).join('')||'<div class="file-empty">'+(s.filter?'没有匹配的文件':g==='staged'?'暂存准备提交的内容':'没有未暂存改动')+'</div>'}`}).join('')}</div><form class="composer" id="commit-form"><div class="composer-label"><span>提交到 <span class="mono">${esc(c.branch||'detached HEAD')}</span></span>${M.isChild()?badge('子模块'):''}</div><input id="commit-title" data-bind="commit-title" value="${esc(c.title)}" placeholder="这次改动做了什么？" aria-label="提交标题"><textarea id="commit-body" data-bind="commit-body" placeholder="补充说明（可选）" aria-label="提交说明">${esc(c.body)}</textarea><div class="composer-foot">${icon('check')}仅提交暂存区，保留其他改动</div><button class="button primary" id="commit-button" type="submit" ${staged&&c.title.trim()&&c.branch&&!s.operation?'':'disabled'}><span>提交 ${staged} 个文件</span><kbd>⌘ ↵</kbd></button>${!c.branch?'<button class="text-button" type="button" data-action="new-branch">先创建分支再提交</button>':''}</form></section>${f?f.type==='module'?moduleDiff(f.module):diff(f,true):`<section class="diff-pane">${empty('工作区干净','所有本地改动已处理。可以查看历史，或切换到另一个工作区。',button('查看提交历史','history')+button('切换 Worktree','worktrees'))}</section>`}</div></div>`}
 function moduleDiff(m){return `<section class="diff-pane"><header class="pane-head"><span class="diff-path">${esc(m.path)}</span>${badge('Submodule')}</header><div class="content-scroll"><div style="padding:20px"><h3 class="section-title" style="margin-top:0">${s.group==='staged'?'已暂存的引用变化':'子模块当前状态'}</h3>${pointerBox(m)}<div class="notice warning"><strong>内部 ${M.dirty(m.id)} 个文件有改动</strong><br>主仓库记录的是子模块提交 SHA。暂存引用不会包含子模块内部尚未提交的文件。</div><div class="button-row">${button(s.group==='staged'?'取消暂存引用':'暂存当前引用','stage-file','data-id="module:'+m.id+'"')}${button('进入子模块','enter-module','data-id="'+m.id+'"','','')}${button('查看详情','select-module','data-id="'+m.id+'"')}</div></div></div></section>`}
 function pointerBox(m){return `<div class="pointer-box"><div class="pointer-row"><span>父仓库 HEAD 记录</span><code>${m.pinned}</code><small>父仓库上次提交的引用</small></div><div class="pointer-row"><span>父仓库 Index 记录</span><code>${m.index}</code><small>下一次父仓库提交将采用的引用</small></div><div class="pointer-row target"><span>子模块当前 HEAD</span><code>${m.initialized?m.head:'尚未检出'}</code><small>${m.initialized?esc(s.scopes[m.id].branch||'detached HEAD'):'需初始化到父仓库记录版本'}</small></div></div>`}
 function historyView(){const entries=M.visibleHistory();if(!entries.length)return `<div class="view">${empty('暂无提交','首次提交后，这里会显示历史线图。',button('返回工作区','workspace'),'history')}</div>`;if(!entries.some(h=>h.sha===s.historySelected))s.historySelected=M.head();const selected=entries.find(h=>h.sha===s.historySelected)||entries[0];s.historySelected=selected.sha;s.historyFile=Math.min(s.historyFile,selected.files.length-1);graphData=M.layoutGraph(entries);const refs=sha=>M.currentRefs().filter(r=>r.sha===sha).map(r=>badge(r.name)).join('');return `<div class="view">${viewHeader('历史线图','提交关系、文件与差异保持联动。',button(icon('branch')+'交互式 Rebase…','rebase'))}<div class="history-layout"><section class="history-left"><div class="history-controls"><div class="legend"><span><i class="line-key"></i>HEAD 第一父链</span><span><i class="line-key secondary"></i>其他提交</span></div><div class="segmented"><button data-action="history-mode" data-mode="graph" class="${s.historyMode==='graph'?'active':''}">线图</button><button data-action="history-mode" data-mode="table" class="${s.historyMode==='table'?'active':''}">关系表</button></div></div><div class="history-scroll">${s.historyMode==='graph'?`<div class="history-rows" id="history-rows"><svg class="history-graph" id="history-graph" aria-hidden="true"></svg>${entries.map(h=>`<button class="history-row ${h.sha===selected.sha?'active':selected.parents.includes(h.sha)?'parent':''}" data-action="select-commit" data-sha="${h.sha}" aria-label="${esc(h.title+'；父提交：'+(h.parents.join(', ')||'无'))}" title="${esc(h.sha+' · 父提交 '+(h.parents.join(', ')||'无'))}"><span class="commit-summary"><span class="subject">${esc(h.title)}</span><span class="refs">${h.sha===M.head()?badge('HEAD'):''}${refs(h.sha)}${h.parents.length>1?badge('Merge'):''}</span><span class="commit-meta"><code>${h.sha}</code><span>${h.time}</span></span></span></button>`).join('')}</div>`:`<table class="history-table"><thead><tr><th>提交</th><th>说明</th><th>父提交</th></tr></thead><tbody>${entries.map(h=>`<tr class="${h.sha===selected.sha?'active':''}"><td><button data-action="select-commit" data-sha="${h.sha}">${h.sha}</button></td><td>${esc(h.title)}</td><td class="mono">${h.parents.join('<br>')||'无'}</td></tr>`).join('')}</tbody></table>`}</div></section><section class="history-detail"><header class="commit-header"><h3>${esc(selected.title)}</h3><div class="commit-info"><code>${selected.sha}</code><span>${selected.author} · ${selected.time}</span>${selected.parents.length>1?badge('合并提交 · 2 个父提交'):''}</div><p>${esc(selected.body)}</p><div class="commit-info"><span>${selected.parents.length>1?'父提交（按合并顺序）':'父提交'}</span>${selected.parents.map((p,i)=>`<button class="parent-link" data-action="select-commit" data-sha="${p}">${selected.parents.length>1?(i+1)+' · ':''}${p}</button>`).join('')||'示例历史边界'}</div><div class="commit-actions">${button('复制 SHA','copy','data-text="'+selected.sha+'"')}${button('Cherry-pick…','cherry-pick','data-sha="'+selected.sha+'"')}${button('Revert…','revert','data-sha="'+selected.sha+'"')}${button('从此创建分支…','new-branch','data-sha="'+selected.sha+'"')}</div></header><div class="commit-diff-layout"><aside class="commit-files">${selected.files.map((f,i)=>fileRow(f,'history-file','data-index="'+i+'"',s.historyFile===i)).join('')}</aside>${diff(selected.files[s.historyFile])}</div></section></div></div>`}
 function branches(){if(M.isChild())return `<div class="view">${viewHeader('子模块分支','子模块使用独立的 Git 历史与分支。')}${empty(M.current().branch||'detached HEAD','可在历史视图查看当前引用；detached HEAD 下先创建分支再提交。',button('创建分支','new-branch')+button('查看独立历史','history'))}</div>`;const rows=(s.branchTab==='remote'?s.remoteBranches:s.branches).filter(b=>b.name.toLowerCase().includes(s.branchFilter.toLowerCase()));return `<div class="view">${viewHeader('分支与远端','看清检出位置与跟踪关系，再执行分支操作。',button(icon('plus')+'创建分支','new-branch'))}<div class="list-toolbar"><div class="segmented">${[['local','本地分支'],['remote','远端分支'],['remotes','远端配置']].map(([id,label])=>`<button data-action="branch-tab" data-tab="${id}" class="${s.branchTab===id?'active':''}">${label}</button>`).join('')}</div><label class="search">${icon('search')}<input id="branch-filter" data-bind="branch-filter" value="${esc(s.branchFilter)}" placeholder="查找分支…" aria-label="查找分支"></label></div><div class="content-scroll"><div class="content-pad">${s.branchTab==='remotes'?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>远端</th><th>Fetch / Push 地址</th><th>操作</th></tr></thead><tbody>${s.remotes.map(r=>`<tr><td class="mono">${esc(r.name)}</td><td class="mono">${esc(r.url)}</td><td>${button('编辑地址','remote-edit','data-name="'+esc(r.name)+'"')}</td></tr>`).join('')}</tbody></table></div><div class="notice">修改远端地址会影响后续 Fetch、Pull 和 Push。示例使用保留域名 example.invalid。</div>`:`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>分支</th><th>最近提交</th><th>跟踪 / 工作目录</th><th>操作</th></tr></thead><tbody>${rows.map(b=>{const wt=s.worktrees.find(w=>s.scopes[w.id].branch===b.name),isCurrent=b.name===M.current().branch;return `<tr class="${isCurrent?'current':''}"><td><div class="name-cell">${icon('branch')}<span class="mono">${esc(b.name)}</span>${isCurrent?badge('当前','accent'):''}</div></td><td class="mono">${b.sha}</td><td>${s.branchTab==='remote'?'远端跟踪引用':esc(b.upstream||'未设置 upstream')}<div class="subline">${wt?'检出于 '+esc(s.scopes[wt.id].name):'未在 worktree 检出'}</div></td><td><div class="button-row">${s.branchTab==='remote'?button('创建跟踪分支','track-branch','data-name="'+esc(b.name)+'"'):wt&&!isCurrent?button('打开工作区','scope','data-id="'+wt.id+'"'):button(isCurrent?'已检出':'检出','checkout','data-name="'+esc(b.name)+'" '+(isCurrent?'disabled':''))}${s.branchTab==='local'?button('更多…','branch-menu','data-name="'+esc(b.name)+'"','',''):''}</div></td></tr>`}).join('')||'<tr><td colspan="4">没有匹配的分支</td></tr>'}</tbody></table></div><div class="notice">在其他 worktree 中检出的分支通过“打开工作区”进入。删除操作会检查占用与未合入提交。</div>`}</div></div></div>`}
 function worktrees(){return `<div class="view">${viewHeader('Worktrees','每个任务有独立目录，切换时保留改动与草稿。',button(icon('plus')+'新建 Worktree','new-worktree'))}<div class="content-scroll"><div class="content-pad"><div class="list-cards">${s.worktrees.map(w=>{const c=s.scopes[w.id],n=M.dirty(w.id);return `<article class="worktree-card ${w.id===s.scope?'current':''}">${icon('tree')}<div><h3>${esc(c.branch)}${w.id===s.scope?badge('当前工作区','accent'):''}${w.id==='main'?badge('主工作区'):''}</h3><p class="path">${esc(c.path)}</p><div class="meta"><span>${n?n+' 个文件有改动':'文件工作区干净'}</span><span>↑ ${c.ahead} 个提交</span><span>${c.title?'保留了提交草稿':'无提交草稿'}</span></div></div><div class="button-row">${button('打开','scope','data-id="'+w.id+'"')}${w.id!=='main'?button('移除…','remove-worktree','data-id="'+w.id+'"'):''}</div></article>`}).join('')}</div><div class="notice">共享 Git 历史与对象库，工作目录、Index 和草稿各自独立。工作区有改动时不能直接移除；移除 worktree 不会自动删除分支。</div></div></div></div>`}
 function submodules(){const m=s.modules.find(m=>m.id===s.selectedModule)||s.modules[0],dirty=M.dirty(m.id),c=s.scopes[m.id];const commits=m.id==='core'?s.coreCommits:[];return `<div class="view">${viewHeader('Submodules','父仓库引用和子模块内部改动分别管理。',button('初始化全部…','init-all'))}<div class="submodule-layout"><aside class="module-tree">${s.modules.map(m=>`<button class="file-row ${m.id===s.selectedModule?'active':''} ${m.parent==='core'?'nested':''}" data-action="select-module" data-id="${m.id}">${icon('box')}<span class="file-info"><strong>${esc(m.path)}</strong><small>${!m.initialized?'未初始化':M.dirty(m.id)?'内部 '+M.dirty(m.id)+' 个文件有改动':m.head!==m.pinned?'引用发生变化':'与记录版本一致'}</small></span><span class="dot ${m.initialized&&(M.dirty(m.id)||m.head!==m.pinned)?'warn':''}"></span></button>`).join('')}</aside><section class="module-main"><div class="module-heading"><div><h3>${esc(m.path)}</h3><p>父仓库：${m.parent==='main'?'sample-workspace':'modules/core'} · ${m.initialized?'已初始化':'未初始化'}</p></div>${m.initialized?button('进入子模块','enter-module','data-id="'+m.id+'"','primary'):button('初始化…','init-module','data-id="'+m.id+'"','primary')}</div>${pointerBox(m)}${!m.initialized?`<div class="notice">初始化会获取子模块内容，并检出父仓库 Index 中记录的版本。默认不会追踪上游最新提交。</div>`:`<div class="notice ${dirty?'warning':''}"><strong>${dirty?'内部有 '+dirty+' 个文件尚未提交':'内部工作区干净'}</strong><br>${dirty?'先在子模块提交，再在父仓库暂存引用变化。':m.head!==m.index?'当前 HEAD 与父仓库暂存引用不同。可以检查差异后暂存新引用。':'子模块当前 HEAD 与父仓库暂存引用一致。'}</div><div class="button-row">${button(m.index!==m.pinned?'取消暂存引用':'暂存当前引用','module-stage','data-id="'+m.id+'"')}${button('检出记录版本…','module-update','data-id="'+m.id+'" data-target="recorded"')}${button('更新到上游…','module-update','data-id="'+m.id+'" data-target="upstream"')}</div><div class="detail-grid"><dl><dt>当前分支</dt><dd>${badge(c.branch||'detached HEAD',c.branch?'accent':'warning')}</dd></dl><dl><dt>发布状态</dt><dd>${m.published===m.head?'当前 HEAD 已推送':c.ahead+' 个提交待推送'}<br><span class="muted mono">远端可达：${m.published}</span></dd></dl></div>${commits.length?`<h4 class="section-title">子模块最近提交</h4>${commits.slice(0,3).map(h=>`<div class="check-row">${icon('history')}<div><span>${esc(h.title)}</span><small class="mono">${h.sha}</small></div></div>`).join('')}`:''}<ol class="steps"><li>在子模块完成提交</li><li>发布子模块提交</li><li>在父仓库提交指针</li><li>推送父仓库</li></ol>`}</section></div></div>`}
 function stash(){const list=s.stashes.filter(x=>x.scope===s.scope),selected=list.find(x=>x.id===s.selectedStash)||list[0];if(selected)s.selectedStash=selected.id;return `<div class="view">${viewHeader('Stash','临时保存当前仓库的改动，检查后再恢复。',button(icon('plus')+'保存当前改动…','new-stash'))}${selected?`<div class="stash-layout"><aside class="stash-list">${list.map((x,i)=>`<button class="stash-item ${x.id===selected.id?'active':''}" data-action="select-stash" data-id="${x.id}"><strong>${esc(x.name)}</strong><small class="mono">stash@{${i}} · ${esc(x.branch||'detached')}</small><small>${x.files.length} 个文件 · ${x.time}</small></button>`).join('')}</aside><section class="stash-main"><header class="commit-header"><h3>${esc(selected.name)}</h3><p>保存于 ${esc(selected.branch||'detached HEAD')} · ${selected.includeUntracked?'包含未跟踪文件':'不包含未跟踪文件'}</p><div class="button-row">${button('应用','apply-stash','data-id="'+selected.id+'"')}${button('应用后移除','pop-stash','data-id="'+selected.id+'"')}${button('删除…','drop-stash','data-id="'+selected.id+'"','danger')}</div></header><div class="commit-diff-layout"><aside class="commit-files">${selected.files.map((f,i)=>fileRow(f,'stash-file','data-index="'+i+'"',s.historyFile===i)).join('')}</aside>${diff(selected.files[Math.min(s.historyFile,selected.files.length-1)])}</div></section></div>`:empty('没有 Stash','可以先保存当前改动，再切换任务。子模块内部改动需要在子模块中保存。',button('保存当前改动','new-stash'),'stash')}</div>`}
 function conflicts(){if(!s.operation)return `<div class="view">${viewHeader('冲突处理','当前没有进行中的合并或 Rebase。')}${empty('没有待解决的冲突','可从评审场景载入一个三方合并样例，查看完整的解决与继续流程。',button('载入合并冲突样例','load-conflict'),'merge')}</div>`;const c=s.conflict;return `<div class="view">${viewHeader(c.file,'三方合并 · 当前分支与合入分支对照，结果区支持手动编辑。',badge(c.resolved?'已标记解决':'1 个文件未解决',c.resolved?'good':'warning'))}<div class="conflict-layout"><div class="conflict-sources"><section class="source-pane"><header><span>当前分支 · ${esc(M.current().branch)}</span>${button('采用当前','resolve-choice','data-choice="ours"')}</header><pre>${esc(c.ours)}</pre></section><section class="source-pane"><header><span>合入分支 · ${esc(s.operation.kind==='rebase'?'正在重放的提交':s.operation.source)}</span>${button('采用合入','resolve-choice','data-choice="theirs"')}</header><pre>${esc(c.theirs)}</pre></section></div><section class="resolution"><header class="resolution-header"><span>合并结果 ${c.resolved?badge('已标记','good'):badge('可编辑')}</span><div class="button-row">${button('查看共同基线','show-base')}${button('采用组合结果','resolve-choice','data-choice="both"')}</div></header><textarea id="conflict-result" data-bind="conflict-result" spellcheck="false" aria-label="合并后的结果">${esc(c.result)}</textarea><footer class="resolution-footer"><span id="conflict-status">${c.resolved?'结果已暂存，可以继续操作。':'先移除冲突标记，再标记为已解决。'}</span><div class="button-row">${button('中止…','abort')}${button('标记已解决','mark-resolved')}${button(s.operation.kind==='rebase'?'继续 Rebase':'完成合并','continue-operation',c.resolved?'':'disabled','primary')}</div></footer></section></div></div>`}
 function rebase(){let problem='';try{M.validateRebase()}catch(e){problem=e.message}return `<div class="view">${viewHeader('交互式 Rebase','按从旧到新的顺序编辑要重放的提交。这里演示显式选择的两条提交。')}<div class="content-scroll"><div class="content-pad"><div class="plan-summary"><span>当前分支</span>${badge(M.current().branch||'detached HEAD','accent')}<span>重放到</span><select id="rebase-target" data-bind="rebase-target" aria-label="Rebase 目标">${s.branches.filter(b=>b.name!==M.current().branch).map(b=>`<option value="${esc(b.name)}" ${s.rebaseTarget===b.name?'selected':''}>${esc(b.name)}</option>`).join('')}</select><span class="muted">范围：c54a916 之后的 2 条提交</span></div><h3 class="section-title">提交顺序 <small class="muted">上方先执行</small></h3>${s.rebasePlan.map((p,i)=>`<div class="rebase-row ${p.action==='drop'?'dropped':''}"><div class="move-controls"><button class="icon-button" data-action="rebase-move" data-index="${i}" data-dir="-1" ${i?'':'disabled'} aria-label="上移提交">↑</button><button class="icon-button" data-action="rebase-move" data-index="${i}" data-dir="1" ${i===s.rebasePlan.length-1?'disabled':''} aria-label="下移提交">↓</button></div><select id="rebase-action-${i}" data-bind="rebase-action" data-index="${i}" aria-label="提交 ${p.sha} 的动作">${['pick','reword','squash','fixup','drop'].map(a=>`<option ${p.action===a?'selected':''}>${a}</option>`).join('')}</select><code>${p.sha}</code>${p.action==='reword'?`<input class="reword" id="rebase-title-${i}" data-bind="rebase-title" data-index="${i}" value="${esc(p.title)}" aria-label="新提交标题">`:`<span class="rebase-title">${esc(p.title)}</span>`}</div>`).join('')}<div class="notice"><strong>pick</strong> 保留 · <strong>reword</strong> 改标题 · <strong>squash</strong> 合并且保留说明 · <strong>fixup</strong> 合并且丢弃说明 · <strong>drop</strong> 丢弃。首个保留提交不能 squash / fixup。</div><div class="form-row inline"><input id="rebase-conflict" type="checkbox" data-bind="rebase-conflict" ${s.rebaseConflict?'checked':''}><label for="rebase-conflict">评审模式：执行到中途时模拟一个内容冲突</label></div>${problem?`<div class="notice warning"><strong>当前不能执行</strong><br>${esc(problem)}</div>`:''}<div class="button-row">${problem&&M.files().length?button('先保存当前改动…','new-stash'):''}${button('预览并执行…','start-rebase',problem?'disabled':'','primary')}${button('返回历史','history')}</div></div></div></div>`}
 function repositories(){const list=[{name:'sample-workspace',path:'~/Projects/sample-workspace',scope:'main',note:'2 个子模块 · 3 个 worktrees'},{name:'sample-review',path:'~/Projects/sample-review',scope:'review',note:'Worktree · review/parser'},...(s.cloneComplete?[{name:'cloned-sample',path:'~/Projects/cloned-sample',scope:'main',note:'刚刚模拟克隆 · 打开后使用主仓库示例状态'}]:[])].filter(r=>(r.name+r.path).toLowerCase().includes(s.repoFilter.toLowerCase()));return `<div class="view"><div class="content-scroll"><section class="repo-home"><h2>继续你的工作</h2><p>打开已有仓库，或从远端克隆。最近工作目录与子模块上下文保持可见。</p><div class="repo-home-head"><label class="search">${icon('search')}<input id="repo-filter" data-bind="repo-filter" value="${esc(s.repoFilter)}" placeholder="查找最近仓库…" aria-label="查找仓库"></label><div class="button-row">${button(icon('folder')+'打开目录…','open-repo')}${button(icon('pull')+'克隆仓库…','clone','','primary')}</div></div>${list.map(r=>`<article class="repo-row">${icon('repo')}<div><h3>${r.name}</h3><p>${r.path}</p><small>${r.note}</small></div><div class="button-row">${button('打开','scope','data-id="'+r.scope+'"')}</div></article>`).join('')||empty('没有匹配的仓库','更换关键词，或打开一个本地目录。',button('打开目录','open-repo'),'search')}<div class="notice">本预览中的目录与 URL 均为示例。打开和克隆只会载入模拟状态，不访问本机文件或远端。</div></section></div></div>`}
 function errorView(){const err=s.networkError||{title:'无法连接远端 origin',detail:'ssh: Could not resolve hostname example.invalid\nfatal: Could not read from remote repository.',command:'git fetch origin'};return `<div class="view"><section class="error-state">${icon('alert')}<h2>${esc(err.title)}</h2><p>本地改动和暂存区保持不变。检查网络、远端地址与访问权限后重试。</p><pre>$ ${esc(err.command)}\n\n${esc(err.detail)}</pre><div class="button-row">${button('重试 Fetch','retry-fetch','','primary')}${button('检查远端配置','remote-config')}${button('返回工作区','workspace')}</div><div class="notice">这是刻意载入的错误场景。重试将展示一次成功的后台操作流程。</div></section></div>`}
 function guide(){return `<div class="view">${viewHeader('页面地图与验收清单','明确每个页面的入口、状态、主要动作与完成条件。',button('回到工作区','workspace'))}<div class="content-scroll"><div class="content-pad"><p class="guide-intro">目标用户是日常使用 Git、也会处理复杂分支与子仓库的开发者。首版 macOS 优先，保留后续跨平台路线。设计强调准确的 Git 状态、持续可见的下一步动作，以及可调的信息密度。</p><div class="guide-map"><section><h3>日常开发</h3><p>仓库入口 → 工作区 → 暂存 → 提交 → 历史检查 → Fetch / Pull / Push</p></section><section><h3>并行任务</h3><p>分支 / Worktree → 独立工作目录 → Stash → 回到原任务</p></section><section><h3>复杂操作</h3><p>Submodule → 独立提交 → 引用更新<br>Rebase / 合并 → 冲突 → 继续或中止</p></section></div><div class="data-table-wrap"><table class="guide-table"><thead><tr><th>工作流</th><th>页面与入口</th><th>可验收行为 / 覆盖状态</th></tr></thead><tbody>${D.guide.map(g=>`<tr><td>${g.title}</td><td>${g.pages}</td><td>${g.accept}<p>${g.states}</p></td></tr>`).join('')}</tbody></table></div><h3 class="section-title">技术选择与交付边界</h3><p class="guide-intro">建议 Rust + GPUI，优先验证中文输入、文本选择、大 diff 和长历史列表。Git 默认使用应用内置、经过验证的 executable，也允许指定系统 Git；工作区写操作按仓库协调，外部修改触发局部刷新。</p><div class="notice warning"><strong>这份交付是设计原型</strong><br>覆盖的是模拟使用闭环，不包含真实文件系统、SSH / 凭据、Git 执行、升级分发或性能结论。冲突演示为单文件，Rebase 演示为两条提交；真实客户端需要扩展多文件、多提交和更多边界状态。首次打开会恢复初始示例，外观与改动只在当前预览中生效。</div><h3 class="section-title">实现时必须补齐的验证</h3><p class="guide-intro">使用真实仓库验证行级暂存、Git hooks、中文与特殊路径、二进制 / 大文件、LFS、符号链接、子模块缺失提交、异常退出恢复和外部并发修改。网络操作必须验证取消与认证失败；删除、历史重写和生产仓库操作需人工复核。</p></div></div></div>`}
 function logDrawer(){return logOpen?`<section class="log-drawer"><header><span>操作记录 · 所有命令均为模拟</span><button class="icon-button" data-action="log" aria-label="关闭操作记录">${icon('close')}</button></header><div class="log-body">${s.logs.slice().reverse().map(l=>`<div class="log-entry"><div>$ ${esc(l.command)}</div><div class="result">${esc(l.result)}</div></div>`).join('')}</div></section>`:''}
 const renderers={workspace,history:historyView,branches,worktrees,submodules,stash,conflicts,rebase,repositories,error:errorView,guide};
 function render(){
  rememberScroll();
  const active=document.activeElement,focusId=active?.id,selection=active&&'selectionStart'in active?active.selectionStart:null;
  s=M.state;applyAppearance();observer?.disconnect();
  const home=s.route==='repositories';$('root').innerHTML=titlebar()+`<div class="shell" ${home?'style="grid-template-columns:minmax(0,1fr)"':''}>${home?'':sidebar()}<section class="main">${home?'':`<nav class="mobile-nav">${D.routes.map(([id,i,label])=>`<button data-action="nav" data-route="${id}" class="${s.route===id?'active':''}">${label}</button>`).join('')}</nav>`+toolbar()+operationBanner()}${(renderers[s.route]||workspace)()}</section></div>`+statusbar()+logDrawer();
  renderModal();const valid=D.scenes.find(([id])=>id===s.route);$('scene').value=valid?s.route:'workspace';
  const hints={history:'选中线图中的提交，右侧会联动展示父提交、文件与 Diff；可直接追溯父节点。',submodules:'完整体验：进入 core → 暂存并提交 → 返回父仓库 → 暂存引用 → 提交 → Push 检查。',conflicts:'对照两侧内容，编辑结果 → 标记解决 → 继续；中止会恢复操作前的示例状态。',rebase:'按顺序编辑计划；首条不能 squash / fixup。可以模拟冲突，处理后继续。',guide:'此处列出页面入口、工作流、状态和验收行为，以及实现时尚需验证的边界。'};$('review-description').textContent=hints[s.route]||'所有操作仅修改当前预览。评审场景可载入特定状态，“重置”恢复初始示例。';
  renderContext=context();const nextContext=renderContext;
  requestAnimationFrame(()=>{restoreScroll(nextContext);drawGraph();if(focusId){const el=$(focusId);if(el&&!el.disabled){el.focus({preventScroll:true});if(selection!==null&&el.setSelectionRange&&['text','search','url','textarea'].includes(el.type))try{el.setSelectionRange(selection,selection)}catch{}}}});
  if($('history-rows')){observer=new ResizeObserver(drawGraph);observer.observe($('history-rows'))}
 }
 function drawGraph(){const svg=$('history-graph'),root=$('history-rows');if(!svg||!root||s.route!=='history')return;const rect=root.getBoundingClientRect(),width=svg.getBoundingClientRect().width;if(!rect.height)return;const maxLane=Math.max(1,...graphData.map(h=>h.lane)),step=Math.min(22,(width-22)/maxLane),points=new Map(),first=M.firstParents();root.querySelectorAll('[data-sha]').forEach(el=>{const h=graphData.find(h=>h.sha===el.dataset.sha);if(h){const r=el.getBoundingClientRect();points.set(h.sha,{x:14+h.lane*step,y:r.top-rect.top+r.height/2,h})}});let edges='',nodes='';for(const h of graphData){const p=points.get(h.sha);if(!p)continue;h.parents.forEach((sha,i)=>{const q=points.get(sha);if(!q)return;const cls=first.has(h.sha)&&i===0&&first.has(sha)?'primary-line':'secondary-line',b=Math.min(18,(q.y-p.y)/2);const d=p.x===q.x?`M${p.x},${p.y}V${q.y}`:p.x<q.x?`M${p.x},${p.y}C${p.x},${p.y+b} ${q.x},${p.y+b} ${q.x},${p.y+2*b}V${q.y}`:`M${p.x},${p.y}V${q.y-2*b}C${p.x},${q.y-b} ${q.x},${q.y-b} ${q.x},${q.y}`;edges+=`<path class="${cls}" d="${d}"/>`});if(h.sha===s.historySelected)nodes+=`<circle class="selection-ring" cx="${p.x}" cy="${p.y}" r="10"/>`;nodes+=`<circle class="node ${first.has(h.sha)?'primary-node':'secondary-node'}" cx="${p.x}" cy="${p.y}" r="${h.parents.length>1?6:5}"/>`;if(h.parents.length>1)nodes+=`<circle class="merge-hole" cx="${p.x}" cy="${p.y}" r="2.5"/>`}svg.setAttribute('viewBox',`0 0 ${width} ${rect.height}`);svg.innerHTML=edges+nodes}
 function modalShell(title,body,footer='',wide=false){return `<section class="modal-overlay" data-backdrop="true"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="关闭">${icon('close')}</button></header><div class="modal-body">${s.modal?.error?`<div class="notice error" role="alert">${esc(s.modal.error)}</div>`:''}${body}</div>${footer?'<footer class="modal-footer">'+footer+'</footer>':''}</div></section>`}
 function input(id,label,value='',placeholder='',type='text'){return `<div class="form-row"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}"></div>`}
 function renderModal(){const m=s.modal;if(!m){$('overlay-root').innerHTML='';return}const cancel=button('取消','close-modal');let html='';
  if(m.type==='command'){html=`<section class="modal-overlay"><div class="modal command-modal" role="dialog" aria-modal="true" aria-label="查找与操作"><div class="command-search">${icon('search')}<input id="command-query" placeholder="输入页面或操作名称…" aria-label="搜索操作"><button class="icon-button" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div><div class="command-list" id="command-list"></div><div class="command-hint">↑ ↓ 选择 · Enter 执行 · Esc 关闭</div></div></section>`}
  else if(m.type==='settings')html=settingsModal();
  else if(m.type==='new-branch')html=modalShell('创建分支',`${input('new-branch-name','分支名',m.name||'','feature/new-task')}<div class="form-row"><label for="new-branch-base">起点提交</label><input id="new-branch-base" value="${esc(m.sha||M.head())}" readonly><small>基于当前选择的提交创建，保留历史引用。</small></div><div class="form-row inline"><input id="branch-checkout" type="checkbox" ${M.isChild()?'checked disabled':'checked'}><label for="branch-checkout">创建后切换到此分支，保留当前改动</label></div>`,cancel+button('创建分支','confirm-new-branch','','primary'));
  else if(m.type==='checkout')html=modalShell('切换到 '+esc(m.name),`<p>当前工作区有未提交改动。选择如何处理，再切换分支。</p><div class="form-row"><label class="radio-option"><input type="radio" name="checkout-policy" value="keep" checked><span>保留改动切换<small>真实客户端需预检目标分支是否会覆盖本地文件。</small></span></label><label class="radio-option"><input type="radio" name="checkout-policy" value="stash"><span>先保存 Stash 再切换<small>仅保存当前仓库的文件；子模块内部改动保持独立。</small></span></label></div>`,cancel+button('切换分支','confirm-checkout','','primary'));
  else if(m.type==='branch-menu'){const b=s.branches.find(b=>b.name===m.name);html=modalShell(esc(m.name),`<p>提交 <code>${b.sha}</code> · ${esc(b.upstream||'未配置 upstream')}</p><div class="list-cards">${button('重命名分支…','rename-branch','data-name="'+esc(m.name)+'"')}${button('删除本地分支…','delete-branch','data-name="'+esc(m.name)+'"','danger')}${button('将当前分支 Rebase 到这里…','rebase-to','data-name="'+esc(m.name)+'" '+(m.name===M.current().branch?'disabled':''))}${button('合并到当前分支…','merge-branch','data-name="'+esc(m.name)+'" '+(m.name===M.current().branch?'disabled':''))}</div>`)}
  else if(m.type==='rename-branch')html=modalShell('重命名分支',input('rename-value','新名称',m.name),cancel+button('重命名','confirm-rename','','primary'));
  else if(m.type==='delete-branch')html=modalShell('删除本地分支？',`<p>将删除 <code>${esc(m.name)}</code>。不会删除远端分支，也不会移除 worktree。</p><div class="notice warning">真实客户端先检查该分支是否有未合入提交；默认使用 git branch -d，有风险时阻止并说明。</div>`,cancel+button('删除本地分支','confirm-delete-branch','','danger'));
  else if(m.type==='new-worktree')html=modalShell('新建 Worktree',`${input('worktree-branch','新分支','feature/new-task')}${input('worktree-path','独立工作目录','~/Projects/sample-new-task')}<div class="form-row"><label for="worktree-base">起点</label><select id="worktree-base">${s.branches.map(b=>`<option value="${b.sha}">${esc(b.name)} · ${b.sha}</option>`).join('')}</select></div><div class="notice">新目录不会携带当前工作区的未提交改动。新分支不能已经在其他 worktree 中检出。</div>`,cancel+button('创建并打开','confirm-worktree','','primary'));
  else if(m.type==='remove-worktree')html=modalShell('移除 Worktree？',`<p>将移除工作目录 <code>${esc(s.scopes[m.id].path)}</code>，保留分支 <code>${esc(s.scopes[m.id].branch)}</code>。</p><div class="notice warning">${M.dirty(m.id)?'该目录有未提交改动，当前无法移除。请先打开并处理。':'仅允许移除干净且非当前使用中的工作目录。'}</div>`,cancel+button('移除工作目录','confirm-remove-worktree','','danger'));
  else if(m.type==='new-stash')html=modalShell('保存当前改动',`${input('stash-name','说明','WIP: '+(M.current().branch||'detached HEAD'))}<div class="form-row inline"><input id="stash-untracked" type="checkbox" checked><label for="stash-untracked">包含未跟踪文件</label></div><div class="notice">保存当前仓库的文件改动及暂存状态。子模块内部改动不随父仓库一起保存。</div>`,cancel+button('保存 Stash','confirm-stash','','primary'));
  else if(m.type==='drop-stash')html=modalShell('删除 Stash？',`<p>将删除 <strong>${esc(s.stashes.find(x=>x.id===m.id)?.name)}</strong>。真实客户端需要明确确认，因为 Git 可能无法直接恢复此记录。</p>`,cancel+button('删除 Stash','confirm-drop-stash','','danger'));
  else if(m.type==='init-module'||m.type==='init-all')html=modalShell('初始化子模块',`<p>获取子模块内容，检出父仓库 Index 中记录的提交。</p><div class="form-row inline"><input id="init-recursive" type="checkbox" checked><label for="init-recursive">同时初始化嵌套子模块</label></div><div class="notice">范围：${m.type==='init-all'?'所有尚未初始化的子模块':esc(s.modules.find(x=>x.id===m.id).path)}。不会改为追踪上游最新版本。</div>`,cancel+button('初始化','confirm-init','','primary'));
  else if(m.type==='module-update'){const sub=s.modules.find(x=>x.id===m.id);html=modalShell(m.target==='recorded'?'检出父仓库记录版本':'更新到上游版本',`<p>${esc(sub.path)} · 当前 HEAD <code>${sub.head}</code></p><div class="form-row"><label for="module-method">更新方式</label><select id="module-method"><option value="checkout">Checkout（检出目标提交，可能 detached HEAD）</option><option value="merge">Merge（合入当前子模块分支）</option></select><small>${m.target==='recorded'?'目标为父仓库暂存区记录 '+sub.index:'获取子模块配置的上游分支最新提交；不自动提交父仓库指针'}</small></div>${M.dirty(m.id)?'<div class="notice warning">子模块内部有改动，当前更新将被阻止。先进入子模块提交或 Stash。</div>':''}`,cancel+button('更新子模块','confirm-module-update','','primary'))}
  else if(m.type==='remote-edit')html=modalShell('编辑远端地址',`${input('remote-url','Fetch / Push URL',s.remotes.find(r=>r.name===m.name)?.url)}<div class="notice">远端名称 ${esc(m.name)} 保持不变。修改只影响后续网络操作。</div>`,cancel+button('保存地址','confirm-remote','','primary'));
  else if(m.type==='push')html=pushModal();
  else if(m.type==='pull')html=modalShell('Pull 前确认',`<p>从 origin 获取更新，并按当前策略更新 <code>${esc(M.current().branch||'detached HEAD')}</code>。</p><div class="form-row"><label for="pull-method">本次策略</label><select id="pull-method">${[['ff','仅 Fast-forward（分叉时停止）'],['rebase','Rebase 本地提交'],['merge','Merge 远端更新']].map(([id,label])=>`<option value="${id}" ${s.settings.pull===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="notice">工作区有改动时先处理；遇到分叉会暂停并展示解决路径，不会默默重写历史。</div>`,cancel+button('执行 Pull','confirm-pull','','primary'));
  else if(m.type==='start-rebase')html=modalShell('确认重写当前分支',`<p>将 ${s.rebasePlan.filter(p=>p.action!=='drop').length} 条保留提交按计划重放到 <code>${esc(s.rebaseTarget)}</code>。</p><div class="notice warning"><strong>提交 SHA 将改变</strong><br>若这些提交已共享，后续 Push 可能需要 force-with-lease。普通 Push 不会自动执行强制推送。</div><p>发生冲突后可以编辑结果、继续，或中止回到操作前状态。</p>`,cancel+button('开始 Rebase','confirm-rebase','','primary'));
  else if(m.type==='abort')html=modalShell('中止当前操作？',`<p>返回 ${s.operation?.kind==='rebase'?'Rebase':'合并'} 开始前的状态；本次冲突结果编辑会被放弃。</p>`,cancel+button('中止并恢复','confirm-abort','','danger'));
  else if(m.type==='show-base')html=modalShell('共同祖先中的内容',`<pre style="white-space:pre-wrap;font:11px/1.9 var(--mono)">${esc(s.conflict.base)}</pre>`,button('返回合并结果','close-modal'));
  else if(m.type==='cherry-pick'||m.type==='revert'){const h=M.rawHistory().find(h=>h.sha===m.sha);html=modalShell(m.type==='cherry-pick'?'Cherry-pick 提交':'Revert 提交',`<p><code>${h.sha}</code> ${esc(h.title)}</p><p>目标分支：<code>${esc(M.current().branch||'detached HEAD')}</code></p>${h.parents.length>1?'<div class="form-row"><label for="mainline">这是合并提交，选择作为 mainline 的父提交</label><select id="mainline"><option value="1">第一父提交</option><option value="2">第二父提交</option></select></div>':''}<div class="notice">${m.type==='revert'?'创建一个反向提交，保留原始历史。':'将所选提交的改动复制到当前分支，产生新的 SHA。'}工作区需要干净；冲突时暂停操作。</div>`,cancel+button('确认并执行','confirm-commit-action','','primary'))}
  else if(m.type==='open-repo')html=modalShell('打开本地仓库',`${input('repo-path','仓库目录','~/Projects/sample-workspace')}<p>此设计稿模拟目录选择。输入包含 sample-review 的路径会打开审查 worktree，其他路径载入主仓库样例。</p>`,cancel+button('打开示例目录','confirm-open-repo','','primary'));
  else if(m.type==='clone')html=modalShell('克隆仓库',`${input('clone-url','远端地址','git@example.invalid:team/cloned-sample.git')}${input('clone-path','本地目录','~/Projects/cloned-sample')}<div class="form-row inline"><input id="clone-recursive" type="checkbox" checked><label for="clone-recursive">同时初始化 Submodules</label></div>`,cancel+button('开始克隆','confirm-clone','','primary'));
  else if(m.type==='progress')html=modalShell(m.title,`<p>${esc(m.description)}</p><div class="progress-track"><i style="width:${m.step/m.steps.length*100}%"></i></div><ul class="progress-steps">${m.steps.map((t,i)=>`<li class="${i<m.step?'done':''}">${icon(i<m.step?'check':'fetch')}${esc(t)}</li>`).join('')}</ul>`,button('取消','cancel-progress'));
  else if(m.type==='merge')html=modalShell('合并分支',`<p>将 <code>${esc(m.name)}</code> 合入 <code>${esc(M.current().branch)}</code>。</p><div class="notice">真实客户端先检查祖先关系。此原型对普通分支模拟创建合并提交；完整冲突流程可从评审场景载入。</div>`,cancel+button('合并','confirm-merge','','primary'));
  $('overlay-root').innerHTML=html;
 }
 function pushModal(){const checks=M.publicationChecks();return modalShell('Push 前检查',`<p><code>${esc(M.current().branch||'detached HEAD')}</code> → <code>origin/${esc(M.current().branch||'HEAD')}</code></p><div class="check-row">${icon('check')}<div>本地分支与目标远端已确认<small>↑ ${M.current().ahead} 个提交；普通 Push 不包含强制推送。</small></div></div>${checks.length?checks.map(m=>`<div class="check-row warning">${icon('alert')}<div>${esc(m.path)} 引用尚未发布<small>父仓库引用 ${m.pinned}；远端可达 ${m.published}</small></div></div>`).join(''):`<div class="check-row good">${icon('check')}<div>当前引用的子模块提交均已发布</div></div>`}${checks.length?'<div class="form-row inline"><input id="push-modules" type="checkbox" checked><label for="push-modules">先推送依赖的子模块，再推送父仓库</label></div>':''}<div class="notice">引用检查失败时停止父仓库 Push，避免其他人拉取后无法检出对应子模块提交。</div>`,button('取消','close-modal')+button('按顺序推送','confirm-push','','primary'))}
 function settingsModal(){const tab=s.settings.tab;let body='';if(tab==='appearance')body=`<div class="setting-block"><label>主题</label><div class="segmented">${[['light','浅色'],['dark','深色'],['system','跟随系统']].map(([id,t])=>`<button data-action="setting-theme" data-value="${id}" class="${s.settings.theme===id?'active':''}">${t}</button>`).join('')}</div></div><div class="setting-block"><label>信息密度</label><div class="segmented">${[['comfortable','舒适'],['compact','紧凑']].map(([id,t])=>`<button data-action="setting-density" data-value="${id}" class="${s.settings.density===id?'active':''}">${t}</button>`).join('')}</div><p>紧凑模式减少列表和代码行高，保留文本可读性。</p></div><div class="setting-block"><label>强调色</label><div class="swatches">${[['teal','#26999d','青色'],['blue','#5b83cb','蓝色'],['plum','#ac799d','梅色']].map(([id,c,t])=>`<button class="swatch ${s.settings.accent===id?'active':''}" data-action="setting-accent" data-value="${id}" style="--swatch:${c}" aria-label="${t}"></button>`).join('')}</div><p>代码增删、警告和历史线图使用独立语义色。</p></div><div class="setting-block"><label for="setting-font">代码字号 <span id="font-label">${s.settings.font} px</span></label><input id="setting-font" type="range" min="11" max="15" value="${s.settings.font}" data-bind="setting-font"></div>`;
  if(tab==='git')body=`<div class="setting-block"><h3>Git executable</h3><label class="radio-option"><input type="radio" name="git-engine" value="bundled" data-bind="git-engine" ${s.settings.git==='bundled'?'checked':''}><span>使用应用内置 Git<small>正式发布时随应用提供经过验证的版本。</small></span></label><label class="radio-option"><input type="radio" name="git-engine" value="system" data-bind="git-engine" ${s.settings.git==='system'?'checked':''}><span>指定系统 Git<small>沿用团队要求的 Git 版本。</small></span></label><input id="git-path" data-bind="git-path" value="${esc(s.settings.gitPath)}" aria-label="系统 Git 路径" ${s.settings.git==='system'?'':'disabled'}><p>SSH、凭据助手和 hooks 由 Git 执行层集成；原型不收集任何凭据。</p></div><div class="setting-block"><label for="pull-default">默认 Pull 策略</label><select id="pull-default" data-bind="pull-default">${[['ff','仅 Fast-forward'],['rebase','Rebase'],['merge','Merge']].map(([id,t])=>`<option value="${id}" ${s.settings.pull===id?'selected':''}>${t}</option>`).join('')}</select><p>分叉或历史重写时展示影响范围，由用户确认继续。</p></div>`;
  if(tab==='keys')body=`<h3 class="section-title" style="margin-top:0">当前可用快捷键</h3><table class="data-table"><tbody><tr><td>查找与操作</td><td><kbd>⌘ K</kbd></td></tr><tr><td>提交暂存内容</td><td><kbd>⌘ ↵</kbd></td></tr><tr><td>暂存 / 取消所选行</td><td><kbd>S</kbd></td></tr><tr><td>关闭弹层</td><td><kbd>Esc</kbd></td></tr><tr><td>命令选择</td><td><kbd>↑ ↓ ↵</kbd></td></tr></tbody></table><p class="muted" style="font-size:10px;line-height:1.9;margin-top:16px">快捷键重映射留待正式设置设计；此处列出的按键均已接入原型。</p>`;
  return `<section class="modal-overlay"><div class="modal wide" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">偏好设置</h2><button class="icon-button" data-action="close-modal" aria-label="关闭设置">${icon('close')}</button></header><div class="settings-layout"><nav class="settings-nav">${[['appearance','外观与布局'],['git','Git 与同步'],['keys','快捷键']].map(([id,t])=>`<button data-action="settings-tab" data-tab="${id}" class="${tab===id?'active':''}">${t}</button>`).join('')}</nav><section class="settings-content">${body}</section></div><footer class="modal-footer"><span class="muted" style="margin-right:auto;font-size:10px;align-self:center">仅在当前预览中生效</span>${button('完成','close-modal','','primary')}</footer></div></section>`;
 }
 function start(){const sel=$('scene');sel.innerHTML=D.scenes.map(([id,t])=>`<option value="${id}">${t}</option>`).join('');const route=location.hash.slice(1);if(renderers[route])s.route=route;render();matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>applyAppearance())}
 return {M,$,esc,icon,button,badge,render,renderModal,toast,navigate,modal,closeModal,start,applyAppearance,get state(){return M.state},toggleLog(){logOpen=!logOpen;render()}};
})();
